styles.css:
/* demo-style-input: 输入框渐变背景 + 聚焦光晕 */
.chat-input-root {
  border-radius: 16px 16px 0 0 !important;
  border: 1px solid rgba(99, 102, 241, 0.3) !important;
  border-bottom: none !important;
  background: linear-gradient(180deg, rgba(99, 102, 241, 0.04) 0%, var(--background-elevated) 40%) !important;
  box-shadow: 0 -2px 20px rgba(99, 102, 241, 0.08);
  transition: box-shadow 0.2s ease, border-color 0.2s ease;
}
.chat-input-root:focus-within {
  border-color: rgba(99, 102, 241, 0.6) !important;
  box-shadow: 0 -4px 30px rgba(99, 102, 241, 0.15), 0 0 0 1px rgba(99, 102, 241, 0.2);
}
/* 发送按钮圆角 + 渐变 */
.chat-input-root button[class*="send"] {
  border-radius: 10px !important;
}

/* demo-style-input: 输入框排版微调 */
.chat-input-root textarea {
  font-size: 14px !important;
  line-height: 1.6 !important;
  letter-spacing: 0.01em;
}
.chat-input-root textarea::placeholder {
  color: rgba(139, 139, 147, 0.6) !important;
  font-style: italic;
}
